/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
/* ========================================================================== */
/* BFusion Portfolio Risk Matrix                                              */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  position: relative;
  overflow: hidden;
  padding-bottom: 24px;
  /* reserve clear-zone for license badge */
  box-sizing: border-box;
  --prm-accent: #E8612A;
  --prm-soft: #F8F9FB;
  --prm-rule: #E5E7EB;
  --prm-text: #242424;
  --prm-muted: #6C757D;
  --prm-title-font: 14px;
  --prm-subtitle-font: 11px;
  --prm-insight-font: 11px;
  --prm-insight-header-font: 13px;
}
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: var(--bf-bg, #FFFFFF);
}
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 12px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
.bfusion-chart-wrap.prm-chart-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  overflow: hidden;
  position: relative;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--prm-soft) 100%);
}
/* ── Header bar ───────────────────────────────────────────────────────── */
.prm-header {
  flex: 0 0 auto;
  min-height: 36px;
  padding: 6px 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--prm-rule);
  background: transparent;
  position: relative;
}
.prm-header__titles {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.prm-header__title {
  font-size: var(--prm-title-font);
  font-weight: 600;
  color: var(--prm-text);
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.prm-header__subtitle {
  font-size: var(--prm-subtitle-font);
  color: var(--prm-muted);
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.prm-header__info {
  flex: 0 0 20px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid var(--bf-rule, #E5E7EB);
  background: var(--bf-tile, #FFFFFF);
  color: var(--bf-muted, #667079);
  font-family: inherit;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  line-height: 1;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: all 0.15s ease;
}
.prm-header__info:hover {
  color: #fff;
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
  outline: none;
}
.prm-header__info:focus-visible {
  outline: 2px solid #D97B29;
  outline-offset: 2px;
}
.prm-header__info:hover,
.prm-header--info-open .prm-header__info {
  background: var(--prm-accent);
  color: #FFFFFF;
  border-color: var(--prm-accent);
}
.prm-info-pop {
  position: absolute;
  top: 40px;
  right: 12px;
  z-index: 30;
  width: 280px;
  max-width: calc(100% - 24px);
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--prm-rule);
  border-radius: 6px;
  padding: 12px 14px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.08);
  font-size: 11.5px;
  color: var(--prm-text);
}
.prm-info-pop__title {
  font-weight: 600;
  color: var(--prm-text);
  margin-bottom: 6px;
  font-size: 12.5px;
}
.prm-info-pop__desc {
  color: var(--prm-muted);
  line-height: 1.45;
  margin-bottom: 8px;
}
.prm-info-pop__list {
  margin: 0;
  padding-left: 16px;
  line-height: 1.55;
  color: var(--prm-text);
}
.prm-info-pop__list li {
  margin-bottom: 2px;
}
/* ── Body row ─────────────────────────────────────────────────────────── */
.prm-body {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: row;
  align-items: stretch;
  overflow: hidden;
  position: relative;
}
.prm-vega {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
}
.prm-vega svg {
  max-width: 100%;
  height: auto;
}
/* ── Insight strip (collapse/expand toggle) ───────────────────────────── */
.prm-insight-strip {
  flex: 0 0 26px;
  width: 26px;
  background: var(--bf-surface-alt, #F4F5F7);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  user-select: none;
  color: var(--bf-muted, #667079);
  gap: 10px;
  transition: background 0.15s ease, color 0.15s ease;
  flex-direction: column;
}
.prm-insight-strip__btn {
  width: 100%;
  height: 100%;
  background: none;
  border: 0;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  color: var(--prm-muted);
}
.prm-insight-strip__arrow {
  color: #D97B29;
  font-size: 10px;
  line-height: 1;
}
.prm-insight-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: 9px;
  font-weight: 650;
  letter-spacing: 0.18em;
  color: var(--bf-muted, #667079);
  text-transform: uppercase;
}
.prm-insight-strip:hover .prm-insight-strip__label {
  color: var(--bf-muted, #667079);
}
/* ── Insight panel ────────────────────────────────────────────────────── */
.prm-insight-panel {
  flex: 0 0 auto;
  width: 0;
  max-width: 320px;
  overflow-y: auto;
  overflow-x: hidden;
  background: linear-gradient(180deg, var(--bf-bg, #FFFFFF) 0%, var(--prm-soft) 100%);
  padding: 12px 14px;
  box-sizing: border-box;
  font-size: var(--prm-insight-font);
  color: var(--prm-text);
}
.prm-body--insight-hidden .prm-insight-strip,
.prm-body--insight-hidden .prm-insight-panel {
  display: none;
}
.prm-body--insight-collapsed .prm-insight-panel {
  display: none;
}
.prm-insight-panel__header {
  border-bottom: 2px solid var(--prm-accent);
  padding-bottom: 8px;
  margin-bottom: 10px;
}
.prm-insight-panel__title {
  font-size: var(--prm-insight-header-font);
  font-weight: 700;
  color: var(--prm-text);
  line-height: 1.2;
}
.prm-insight-panel__count {
  font-size: calc(var(--prm-insight-font) - 1px);
  color: var(--prm-muted);
  margin-top: 2px;
}
.prm-insight-panel__kpis {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 12px;
}
.prm-kpi {
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid var(--prm-rule);
  border-left: 3px solid var(--prm-accent);
  border-radius: 4px;
  padding: 8px 10px;
}
.prm-kpi--triage {
  border-left-color: #E74C3C;
}
.prm-kpi__value {
  font-size: calc(var(--prm-insight-header-font) + 4px);
  font-weight: 700;
  color: var(--prm-text);
  line-height: 1.1;
}
.prm-kpi__label {
  font-size: calc(var(--prm-insight-font) - 1px);
  color: var(--prm-muted);
  margin-top: 2px;
  line-height: 1.3;
}
.prm-insight-panel__smart {
  margin: 0 0 12px 0;
  padding-left: 16px;
  line-height: 1.55;
  color: var(--prm-text);
}
.prm-insight-panel__smart li {
  margin-bottom: 4px;
}
.prm-insight-panel__smart strong {
  color: var(--prm-accent);
  font-weight: 700;
}
.prm-insight-panel__section {
  margin-bottom: 12px;
}
.prm-insight-panel__section-title {
  font-size: calc(var(--prm-insight-font) - 1px);
  font-weight: 700;
  color: var(--prm-text);
  letter-spacing: 0.3px;
  margin-bottom: 6px;
  text-transform: uppercase;
}
.prm-insight-panel__list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.prm-insight-panel__list li {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 0;
  border-bottom: 1px dashed var(--prm-rule);
}
.prm-insight-panel__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--prm-accent);
  flex: 0 0 6px;
}
.prm-insight-panel__name {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--prm-text);
}
.prm-insight-panel__val {
  flex: 0 0 auto;
  font-weight: 600;
  color: var(--prm-muted);
}
.prm-insight-panel__escalation,
.prm-insight-panel__ok {
  border-radius: 6px;
  padding: 8px 10px;
  margin-top: 8px;
}
.prm-insight-panel__escalation {
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid #FEB2B2;
}
.prm-insight-panel__ok {
  background: var(--bf-bg, #FFFFFF);
  border: 1px solid #9AE6B4;
}
.prm-insight-panel__escalation-label {
  font-size: calc(var(--prm-insight-font) - 2px);
  font-weight: 700;
  letter-spacing: 0.3px;
  margin-bottom: 4px;
  color: #E53E3E;
}
.prm-insight-panel__ok .prm-insight-panel__escalation-label {
  color: #2F855A;
}
.prm-insight-panel__escalation-value {
  font-size: var(--prm-insight-font);
  font-weight: 700;
  color: #C53030;
}
.prm-insight-panel__ok-value {
  font-size: var(--prm-insight-font);
  font-weight: 600;
  color: #276749;
}
/* ── Landing page (unchanged) ─────────────────────────────────────────── */
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted, #667079);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text, #242424);
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule, #E5E7EB);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
  font-weight: 400;
}
.bfusion-landing__metadata a {
  color: var(--bf-muted, #667079);
  text-decoration: none;
}
.bfusion-landing__metadata a:hover {
  text-decoration: underline;
}
/* ========================================================================== */
/* License Badge & Watermark                                                   */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
